SELECT * FROM (
    SELECT t.*, ROWNUM rn FROM (
        SELECT * FROM CUSTOMER WHERE IS_DELETED = 0

            AND (CUST_NAME LIKE '%' || #{keyword} || '%'
              OR PHONE     LIKE '%' || #{keyword} || '%'
              OR ID_CARD   LIKE '%' || #{keyword} || '%')


            AND VIP_LEVEL = #{vipLevel}


    ) t WHERE ROWNUM <= #{offset} + #{limit}
) WHERE rn > #{offset}

SELECT COUNT(1) FROM CUSTOMER WHERE IS_DELETED = 0
AND (CUST_NAME LIKE '%' || #{keyword} || '%' OR PHONE LIKE '%' || #{keyword} || '%' OR ID_CARD LIKE '%' || #{keyword} || '%')
AND VIP_LEVEL = #{vipLevel}
